class Solution {
    public boolean checkArray(int[] nums, int k) {
        int n = nums.length;
        int[] diff = new int[n + 1];
        int activeSubtract = 0;

        for (int i = 0; i < n; i++) {
            activeSubtract += diff[i];
            int value = nums[i] + activeSubtract;
            if (value < 0) return false;
            if (value == 0) continue;
            if (i + k > n) return false;

            activeSubtract -= value;
            diff[i + k] += value;
        }
        return true;
    }
}
